    brx: "सोरखारि सुबिदा, आजेवनाय बिथांखि आरो बिफाननि सासनखौ मोननो नोंथांनि थाखोखौ सायख'।",
    mni: "পব্লিক সর্ভিসেস, স্কিম বেনিফিৎস অমসুং দিপার্তমেন্তেল এডমিনিস্ত্রেসন এক্সেস তৌনবগীদমক নহাক্কী কাংলুপ খনবীয়ু।",
    sd: "عوامي خدمتن، اسڪيم جي فائدن ۽ شعبي واري انتظاميه تائين رسائي حاصل ڪرڻ لاءِ پنهنجو درجو چونڊيو.",
